#!/usr/bin/env python3
"""Repeatable MCPJam CLI checks; no account credentials or model credits needed."""
import datetime,json,os,pathlib,subprocess,sys
root=pathlib.Path(__file__).resolve().parent
cli=root/'node_modules/.bin/mcpjam'
url=os.environ.get('MCP_SERVER_URL','http://fixture:8765/mcp')
out=root/'results'; out.mkdir(exist_ok=True)
cases=[('positive',{'a':2,'b':3},5),('negative',{'a':-7,'b':2},-5),('zero',{'a':0,'b':0},0),('decimal',{'a':1.25,'b':2.5},3.75),('cancellation',{'a':1000000,'b':-1000000},0),('missing',{'a':2},None),('wrong_type',{'a':'2','b':3},None),('extra_property',{'a':2,'b':3,'c':4},None)]
rows=[]
for name,args,expected in cases:
 cmd=[str(cli),'tools','call','--url',url,'--tool-name','add','--tool-args',json.dumps(args),'--quiet','--format','json','--debug-out',str(out/(name+'-trace.json'))]
 p=subprocess.run(cmd,capture_output=True,text=True,timeout=20)
 (out/(name+'.stdout')).write_text(p.stdout); (out/(name+'.stderr')).write_text(p.stderr)
 try: data=json.loads(p.stdout)
 except ValueError: data={}
 # Invalid-input cases require an error visible in a result or the captured RPC trace.
 trace_path=out/(name+'-trace.json')
 trace=json.loads(trace_path.read_text()) if trace_path.exists() else {}
 def rpc_errors(obj):
  if isinstance(obj,dict):
   if obj.get('jsonrpc')=='2.0' and 'error' in obj: yield obj['error']
   for v in obj.values(): yield from rpc_errors(v)
  elif isinstance(obj,list):
   for v in obj: yield from rpc_errors(v)
 errors=list(rpc_errors(trace))
 if expected is None:
  passed=bool(data.get('isError') or errors)
 else:
  structured=data.get('structuredContent',{})
  texts=[json.loads(c['text']) for c in data.get('content',[]) if c.get('type')=='text']
  passed=p.returncode==0 and not data.get('isError') and structured.get('sum')==expected and any(t.get('sum')==expected for t in texts)
 row={'name':name,'arguments':args,'expected':expected if expected is not None else 'reject invalid input','passed':passed,'exitCode':p.returncode,'result':data,'rpcErrors':errors}
 rows.append(row); print(('PASS' if passed else 'FAIL')+' '+name+' '+json.dumps(data))
report={'generatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':url,'cliVersion':subprocess.check_output([str(cli),'--version'],text=True).strip(),'passed':sum(r['passed'] for r in rows),'total':len(rows),'cases':rows}
(out/'summary.json').write_text(json.dumps(report,indent=2)+'\n')
sys.exit(0 if all(r['passed'] for r in rows) else 1)
PY
